import{_ as r,C as o,o as i,c as s,a0 as a,b as l,w as t,a as c,E as d,a1 as u}from"./chunks/framework.DYS8d9tm.js";const v=JSON.parse('{"title":"🏛️ System Architecture Deep Dive","description":"","frontmatter":{},"headers":[],"relativePath":"technical/architecture/system_overview.md","filePath":"technical/architecture/system_overview.md"}'),m={name:"technical/architecture/system_overview.md"};function h(p,e,g,y,A,b){const n=o("Mermaid");return i(),s("div",null,[e[1]||(e[1]=a('<h1 id="🏛️-system-architecture-deep-dive" tabindex="-1">🏛️ System Architecture Deep Dive <a class="header-anchor" href="#🏛️-system-architecture-deep-dive" aria-label="Permalink to &quot;🏛️ System Architecture Deep Dive&quot;">​</a></h1><p>WealthFam is engineered as a high-concurrency, modular microservice ecosystem. Each component is architecturally decoupled to ensure systematic resilience, Precision accuracy, and local-first data privacy.</p><hr><h2 id="🧩-architectural-philosophy" tabindex="-1">🧩 Architectural Philosophy <a class="header-anchor" href="#🧩-architectural-philosophy" aria-label="Permalink to &quot;🧩 Architectural Philosophy&quot;">​</a></h2><ul><li><strong>Modular Microservices</strong>: Every core pillar (Backend, Frontend, Parser, Mobile) exists as an independent unit. This allows for categorical scaling and simplifies regression testing.</li><li><strong>Sovereign Circle Model</strong>: Unlike traditional cloud-first apps, WealthFam creates a &quot;Sovereign Circle&quot; around your data. Your backend database (PostgreSQL) is isolated, and all parser/AI ingestion processing is kept local and distinct per tenant.</li><li><strong>Precision Ledger Integrity</strong>: Every transaction ingested is subjected to deterministic hashing (MD5/SHA256). This ensures that no data point is duplicated across the SMS, Email, or Manual ingestion streams.</li><li><strong>AI-Augmented Parsing</strong>: We utilize Google Gemini for unstructured data extraction, acting as a high-intelligence fallback when traditional regex patterns fail.</li></ul><hr><h2 id="📡-core-component-taxonomy" tabindex="-1">📡 Core Component Taxonomy <a class="header-anchor" href="#📡-core-component-taxonomy" aria-label="Permalink to &quot;📡 Core Component Taxonomy&quot;">​</a></h2><h3 id="_1-the-core-engine-backend" tabindex="-1">1. The Core Engine (Backend) <a class="header-anchor" href="#_1-the-core-engine-backend" aria-label="Permalink to &quot;1. The Core Engine (Backend)&quot;">​</a></h3><ul><li><strong>Framework</strong>: FastAPI (Asynchronous Python)</li><li><strong>Persistence</strong>: PostgreSQL (Core relational ledger) and DuckDB (Enterprise Admin telemetry &amp; logs)</li><li><strong>Responsibility</strong>: Serving as the relational orchestrator, managing the lifecycle of financial entities, enforcing strict schema validation via Pydantic (strict=True), and ensuring absolute mathematical precision via a global <strong>Decimal standard</strong>.</li></ul><h3 id="_2-the-precision-harvester-parser" tabindex="-1">2. The Precision Harvester (Parser) <a class="header-anchor" href="#_2-the-precision-harvester-parser" aria-label="Permalink to &quot;2. The Precision Harvester (Parser)&quot;">​</a></h3><ul><li><strong>Framework</strong>: Python Microservice (FastAPI)</li><li><strong>Architecture</strong>: 100% Stateless &amp; Code-Driven Engine (&lt; 0.5ms extraction, in-memory 5-minute LRU duplicate submission guard, zero financial PII stored at rest)</li><li><strong>Logic</strong>: Native compiled Python bank parsers and PDF statement extractors (HDFC, ICICI, SBI, Axis, Kotak, etc.) with asynchronous scrubbed telemetry shipping to Admin-Backend</li><li><strong>Responsibility</strong>: Real-time deterministic normalization of raw SMS, Email, Bank Statement, and CAS payloads into the unified transactional schema.</li></ul><h3 id="_3-the-wealthhub-web-app" tabindex="-1">3. The WealthHub (Web App) <a class="header-anchor" href="#_3-the-wealthhub-web-app" aria-label="Permalink to &quot;3. The WealthHub (Web App)&quot;">​</a></h3><ul><li><strong>Framework</strong>: Vue 3 + Vite</li><li><strong>UI System</strong>: Material 3 / Triage Design Language</li><li><strong>Responsibility</strong>: Advanced data visualization, Precision auditing of transactions, and comprehensive budget management.</li></ul><h3 id="_4-precision-pulse-mobile-app" tabindex="-1">4. Precision Pulse (Mobile App) <a class="header-anchor" href="#_4-precision-pulse-mobile-app" aria-label="Permalink to &quot;4. Precision Pulse (Mobile App)&quot;">​</a></h3><ul><li><strong>Framework</strong>: Flutter (Native Android)</li><li><strong>Background Engine</strong>: Android Foreground Services</li><li><strong>Responsibility</strong>: Non-intrusive SMS listening, real-time synchronization with the Sovereign Circle backend, and offline-cached anonymous client telemetry (app lifecycles, SMS listener heartbeats, batch sync timings, sanitized crash signatures).</li></ul><h3 id="_5-enterprise-admin-telemetry-control-plane-admin-backend-admin-web" tabindex="-1">5. Enterprise Admin &amp; Telemetry Control Plane (<code>Admin-Backend</code> &amp; <code>Admin-Web</code>) <a class="header-anchor" href="#_5-enterprise-admin-telemetry-control-plane-admin-backend-admin-web" aria-label="Permalink to &quot;5. Enterprise Admin &amp; Telemetry Control Plane (`Admin-Backend` &amp; `Admin-Web`)&quot;">​</a></h3><ul><li><strong>Framework</strong>: FastAPI (<code>:8002</code>) + Vue 3 (<code>:5174</code> dev / <code>:8080</code> Docker)</li><li><strong>Persistence</strong>: Embedded DuckDB Timeseries (<code>data/telemetry.duckdb</code>) &amp; <code>data/logos/</code> assets (Zero direct PostgreSQL connections)</li><li><strong>Communication</strong>: Strictly proxies requests to <code>Backend</code> (<code>:8000</code>) and <code>Parser</code> (<code>:8001</code>) via REST APIs (<code>httpx</code>)</li><li><strong>Responsibility</strong>: Unified zero-PII telemetry &amp; sanitized log ingestion, 30s active endpoint SLA probing, code-first Parser Testing Studio &amp; multi-source sandbox (SMS/Email text tester, scratchpad regex prototyping, and live PDF statement inspection via <code>pdfplumber</code>), consent-driven training inbox with format-preserving structural anonymization and deduplication counters, and Brand Logo/Regex management. Completely isolated from client financial data.</li></ul><h3 id="_6-anonymous-telemetry-observability-pipeline" tabindex="-1">6. Anonymous Telemetry &amp; Observability Pipeline <a class="header-anchor" href="#_6-anonymous-telemetry-observability-pipeline" aria-label="Permalink to &quot;6. Anonymous Telemetry &amp; Observability Pipeline&quot;">​</a></h3><ul><li><strong>Philosophy</strong>: Mathematical zero-PII assurance. All routes are normalized to parameterized templates (<code>/api/v1/finance/accounts/{id}</code>), logs are scrubbed at the client/producer before leaving the process (stripping JWTs, emails, PANs, currencies, account numbers, and phone numbers).</li><li><strong>Producers</strong>: <ul><li><code>Backend</code>: Non-blocking ASGI <code>TelemetryMiddleware</code> + <code>AsyncHttpLogHandler</code> with anti-recursion guards and background load-shedding queues flushing to <code>Admin-Backend</code>. Exposes <code>POST /api/v1/telemetry/ingest</code> proxying for mobile clients.</li><li><code>Parser</code>: ASGI middleware, <code>AsyncHttpLogHandler</code>, and pipeline extraction metrics (<code>record_parser_event</code>).</li><li><code>Web-App</code>: Client-side navigation latencies, API error rates, and unhandled Vue exceptions, with <code>sendBeacon</code> on page unload and transparent user onboarding/settings toggles.</li><li><code>Mobile-App</code>: Offline-first <code>SharedPreferences</code> event queue (FIFO 100 max) surviving network outages, with decoupled target URL resolution (<code>backendUrl</code> proxy or <code>dedicatedTelemetryUrl</code>).</li></ul></li></ul><hr><h2 id="🔄-data-lifecycle-synchronization" tabindex="-1">🔄 Data Lifecycle &amp; Synchronization <a class="header-anchor" href="#🔄-data-lifecycle-synchronization" aria-label="Permalink to &quot;🔄 Data Lifecycle &amp; Synchronization&quot;">​</a></h2>',21)),(i(),l(u,null,{default:t(()=>[d(n,{id:"mermaid-187",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20S%20as%20Source%20(SMS%2FMail%2FFile)%0A%20%20%20%20participant%20B%20as%20FastAPI%20Backend%20(%3A8000)%0A%20%20%20%20participant%20P%20as%20Stateless%20Parser%20(%3A8001)%0A%20%20%20%20participant%20PG%20as%20PostgreSQL%20Storage%20(%3A5432)%0A%20%20%20%20participant%20A%20as%20Admin%20Studio%20DuckDB%20(%3A8002)%0A%20%20%20%20participant%20F%20as%20Vue%20%2F%20Flutter%20Client%0A%0A%20%20%20%20Note%20over%20S%2C%20B%3A%201.%20Ingestion%20Dispatch%0A%20%20%20%20S-%3E%3EB%3A%20Raw%20Financial%20Payload%0A%0A%20%20%20%20Note%20over%20B%2C%20P%3A%202.%20In-Memory%20Parsing%20%26%20Idempotency%0A%20%20%20%20B-%3E%3EP%3A%20POST%20%2Fv1%2Fingest%2F*%20(Internal%20JWT)%0A%20%20%20%20P-%3E%3EP%3A%20RecentSubmissionCache%20(5m%20LRU)%0A%20%20%20%20P-%3E%3EP%3A%20Native%20Bank%20Registry%20(Compiled%20Regex)%0A%20%20%20%20P--%3E%3EA%3A%20Scrubbed%20Telemetry%20Stream%20(Async)%0A%20%20%20%20P-%3E%3EB%3A%20Structured%20Transaction%20JSON%0A%0A%20%20%20%20Note%20over%20B%2C%20PG%3A%203.%20Cross-Source%20Deduplication%20%26%20Persistence%0A%20%20%20%20B-%3E%3EB%3A%20TransactionDeduplicator%20(Ref%20ID%2C%20Hash%2C%203-Day%20Window)%0A%20%20%20%20alt%20Unique%20Transaction%0A%20%20%20%20%20%20%20%20B-%3E%3EPG%3A%20SQL%20Insert%20%2B%20Categorization%20%2B%20Audit%0A%20%20%20%20%20%20%20%20PG--%3E%3EB%3A%20Confirmed%20Row%0A%20%20%20%20%20%20%20%20Note%20over%20B%2C%20F%3A%204.%20Real-Time%20Push%0A%20%20%20%20%20%20%20%20B-%3E%3EF%3A%20WebSocket%20%2F%20REST%20Push%20Notification%0A%20%20%20%20else%20Duplicate%20Transaction%0A%20%20%20%20%20%20%20%20B-%3E%3EPG%3A%20Mark%20duplicate_skipped%20(Enrich%20GPS%20if%20available)%0A%20%20%20%20end%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="🛡️-security-privacy-the-sovereign-circle" tabindex="-1">🛡️ Security &amp; Privacy: The Sovereign Circle <a class="header-anchor" href="#🛡️-security-privacy-the-sovereign-circle" aria-label="Permalink to &quot;🛡️ Security &amp; Privacy: The Sovereign Circle&quot;">​</a></h2><ol><li><strong>Isolation</strong>: Your backend instance is locally managed. Your data is never pooled or used for training external models.</li><li><strong>Encryption</strong>: Communication between services is secured via TLS, and sensitivity labels are applied to all financial metadata.</li><li><strong>Auditability &amp; Integrity</strong>: Every mutation in the database is anchored with a Precision audit trail. Our <strong>Soft-Delete Architecture</strong> (using <code>is_deleted</code> flags) ensures that historical financial mappings are never permanently lost, allowing for complete transaction reconstruction and point-in-time auditing.</li><li><strong>Absolute Precision</strong>: To prevent longitudinal wealth drift, all financial calculations are performed using the <strong>Decimal</strong> standard. This eliminates the accumulated rounding errors inherent in floating-point arithmetic.</li><li><strong>Identity Preservation</strong>: High-frequency recalculations (e.g., Mutual Fund average cost rebuilding) utilize surgical <strong>In-Place Updates</strong>. This preserves entity UUIDs across the entire lifecycle, ensuring that frontend caches, goals, and history links remain perfectly synchronized.</li></ol><hr><div align="center"> *Architecture for a Lifetime · Privacy by Design · Precision by Heart* *Made with ❤️ by WGLabz* </div>',5))])}const f=r(m,[["render",h]]);export{v as __pageData,f as default};
